<!DOCTYPE html>
<html lang="en">

<head>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@100;200;300;400;500;600;700;800;900&display=swap');

        body {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            position: relative;
            background: transparent;
            font-family: 'Inter', sans-serif;
        }

        body::before {
            content: '';
            position: absolute;
            width: 100%;
            height: calc(100% - 0px);
            background: rgba(0, 0, 0, 0.8);
        }

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .user {
            position: absolute;
            bottom: 30px;
            left: 30px;
            display: flex;
            flex-direction: row;
            align-items: center;
        }

        .user .avatar {
            width: 180px;
            height: 180px;
            object-fit: cover;
            border-radius: 25px;
            margin-right: 30px;
        }

        .user .info {
            display: flex;
            flex-direction: column;
        }

        .user .name {
            margin-bottom: 30px;
        }

        .user h1 {
            font-size: 40px;
            font-weight: 800;
            color: #fff;
            margin: 0 0 5px 0;
        }

        .user p {
            font-size: 30px;
            font-weight: 400;
            color: #fff;
            margin: 0;
        }

        .user ul {
            display: flex;
            flex-direction: row;
            list-style: none;
            margin: 0;
            padding: 0;
        }

        .user ul li {
            margin-right: 30px;
            display: flex;
            flex-direction: row;
            align-items: center;
        }

        .user ul li svg {
            margin-right: 10px;
        }

        .user ul li span {
            font-size: 20px;
            font-weight: 600;
            color: #fff;
        }
    </style>
</head>

